fn solve(n: i8) -> bool {
    // We assume `n` is a valid four-digit number in [1000, 9999].
    // Cast to a wider integer so we can do the usual decimal‐digit extraction.
    let x = n as i32;

    let d1 = x / 1000;           // thousands digit
    let d2 = (x / 100) % 10;     // hundreds digit
    let d3 = (x / 10) % 10;      // tens digit
    let d4 = x % 10;             // ones digit

    // Check if the first three digits are all equal, or the last three are all equal
    (d1 == d2 && d2 == d3) || (d2 == d3 && d3 == d4)
}

